const clampInteger=(v,min,max,fallback)=>Number.isSafeInteger(v)?Math.max(min,Math.min(max,v)):fallback;
function normalizeDisaster(c){for(const kind of ['duration','population','bunkerArea']){const conf=RANGE_CONFIG[kind],r=c[kind+'Range'],v=Number(c[kind]),target=Number.isFinite(r?.max)?r.max:Number.isFinite(v)?v:conf.presets[0][1];const preset=conf.presets.find(([min,max])=>r?.min===min&&r?.max===max)||conf.presets.find(([min,max])=>target>=min&&target<=max)||conf.presets[conf.presets.length-1];c[kind+'Range']={min:preset[0],max:preset[1]};}if(!c.images||typeof c.images!=='object')c.images={};}
function validDisasterImage(record,spec){return !!record&&!record.verificationError&&typeof record.assetId==='string'&&record.width===spec.width&&record.height===spec.height&&Number.isInteger(record.bytes)&&record.bytes>0&&record.bytes<=MAX_DISASTER_IMAGE&&['image/jpeg','image/png','image/webp'].includes(record.mime);}
function disasterIssues(c){const issues=[],name=c.name?.trim()||'Катастрофа без названия';for(const spec of DISASTER_IMAGES)if(!validDisasterImage(c.images?.[spec.id],spec))issues.push(name+': загрузите «'+spec.name+'» ('+spec.width+' × '+spec.height+' px, до 1 МБ).');for(const kind of ['duration','population','bunkerArea']){const r=c[kind+'Range'],conf=RANGE_CONFIG[kind];if(!r||!Number.isSafeInteger(r.min)||!Number.isSafeInteger(r.max)||r.min<conf.min||r.max>conf.max||r.min>r.max||!conf.presets.some(p=>p[0]===r.min&&p[1]===r.max))issues.push(name+': проверьте диапазон «'+conf.title+'».');}return issues;}
let disasterDbPromise;
function assetDb(){if(!disasterDbPromise)disasterDbPromise=new Promise((resolve,reject)=>{const req=indexedDB.open('shelter42-workshop-assets',1);req.onupgradeneeded=()=>req.result.createObjectStore('images');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});return disasterDbPromise;}
async function saveDisasterAsset(id,file){const db=await assetDb();await new Promise((resolve,reject)=>{const tx=db.transaction('images','readwrite');tx.objectStore('images').put(file,id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});}
async function readDisasterAsset(id){const db=await assetDb();return new Promise((resolve,reject)=>{const req=db.transaction('images','readonly').objectStore('images').get(id);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
async function hydrateDisasterImages(){try{for(const p of library)for(const c of p.cards.disaster||[])for(const rec of Object.values(c.images||{})){if(!rec?.assetId||disasterAssetUrls.has(rec.assetId))continue;const blob=await readDisasterAsset(rec.assetId);if(blob)disasterAssetUrls.set(rec.assetId,URL.createObjectURL(blob));}document.querySelectorAll('img[data-disaster-asset]').forEach(img=>{const url=disasterAssetUrls.get(img.dataset.disasterAsset);if(url){img.src=url;img.hidden=false;}});}catch{toast('Не удалось прочитать изображения с устройства.');}}
