 return '<div class="card-editor" data-constructor-card="'+esc(c.id)+'"><section class="form-stage card-content-stage">'+(special?'<div class="notice neutral mechanic-notice">'+icon('lock')+'<div><strong>Механика закреплена · только чтение</strong>'+esc(template.mechanic)+'</div></div>':'')+field('Название карты',c.name,'name',{card:c.id,max:30,hint:'Не более 30 символов.'})+typePicker(c)+field('Описание',c.description,'description',{card:c.id,type:'textarea',max:section==='disaster'?1200:130,hint:'Не более '+(section==='disaster'?1200:130)+' символов.'})+relation+'</section>'+features+(section==='disaster'?rangeSelector(c,'duration')+rangeSelector(c,'population')+rangeSelector(c,'bunkerArea')+'<section class="form-stage image-stage">'+disasterImageFields(c)+'</section>'+constructorAudio(c):section==='bunker'?'<section class="form-stage image-stage">'+media(c.image)+'</section>':'')+'<div class="card-actions">'+btn('Удалить','danger push','data-delete="'+c.id+'"')+btn('Сохранить','primary','data-close="'+c.id+'"')+'</div></div>';
