function reviewDisasterDetails(){const cards=pack.cards.disaster.filter(c=>!c.name.trim()||!c.description.trim()||disasterIssues(c).length);if(!cards.length)return '';return '<details class="review-disaster-details"><summary>'+icon('down')+'<span>Какие катастрофы исправить · '+cards.length+'</span></summary><ul>'+cards.map(c=>{const count=DISASTER_IMAGES.filter(spec=>validDisasterImage(c.images?.[spec.id],spec)).length;return '<li><div><strong>'+esc(c.name||'Без названия')+'</strong><p class="hint">'+[!c.name.trim()?'Нет названия':'',!c.description.trim()?'Нет описания':'',count<4?'Изображения: '+count+' / 4':'',disasterIssues(c).some(x=>!x.includes('загрузите'))&&count===4?'Проверьте параметры':''].filter(Boolean).join(' · ')+'</p></div>'+btn('Исправить','small','data-review-disaster="'+esc(c.id)+'"')+'</li>';}).join('')+'</ul></details>';}
