function showModal(html){const modal=$('#modal');modal.classList.remove('editor-dialog','rules-dialog','confirm-dialog');modal.innerHTML=html;const header=document.createElement('header');header.className='modal-header';const body=document.createElement('div');body.className='modal-body';const footer=document.createElement('footer');footer.className='modal-footer';const titleBlock=modal.querySelector('.rules-title');if(titleBlock)header.append(titleBlock);else{const title=modal.querySelector('h2');if(title){const description=title.nextElementSibling?.tagName==='P'?title.nextElementSibling:null;header.append(title);if(description)header.append(description);}}const title=header.querySelector('h2');if(title){title.id='modal-title';title.tabIndex=-1;modal.setAttribute('aria-labelledby','modal-title');}else modal.removeAttribute('aria-labelledby');while(modal.firstChild)body.append(modal.firstChild);const cancel=document.createElement('button');cancel.type='button';cancel.className='btn';cancel.dataset.modalClose='true';cancel.textContent='Закрыть';let extra=null;const confirm=body.querySelector('[data-confirm-delete],[data-confirm-pack-delete]'),form=body.querySelector('form'),cardActions=body.querySelector('.card-actions'),templateAction=body.querySelector('[data-add-template]');body.querySelectorAll('[data-modal-close]').forEach(button=>button.remove());const statusAction=body.querySelector('[data-confirm-pack-status]');if(statusAction){cancel.textContent='Отмена';footer.append(cancel,statusAction);}else if(confirm){modal.classList.add('confirm-dialog');cancel.textContent='Отмена';cancel.classList.add('primary');confirm.classList.add('modal-destructive');footer.append(confirm,cancel);}else if(form){const submit=form.querySelector('button[type="submit"]');cancel.textContent='Отмена';if(submit){submit.setAttribute('form',form.id);footer.append(cancel,submit);}else footer.append(cancel);}else if(cardActions){const done=cardActions.querySelector('[data-close]');footer.append(cancel);if(done)footer.append(done);cardActions.querySelectorAll('[data-preview],[data-duplicate]').forEach(button=>button.remove());const remove=cardActions.querySelector('[data-delete]');if(remove){remove.className='btn editor-delete-icon';remove.innerHTML=icon('trash');remove.title='Удалить карточку';remove.setAttribute('aria-label','Удалить карточку');footer.append(remove);}cardActions.remove();}else if(templateAction){templateAction.classList.add('primary');footer.append(cancel,templateAction);}else{cancel.classList.add('primary');footer.append(cancel);}body.querySelectorAll('.dialog-actions').forEach(row=>{if(!row.children.length)row.remove();});modal.replaceChildren(header,body,footer);if(extra)modal.append(extra);decorateKitControls();if(!modal.open)modal.showModal();if(confirm)cancel.focus();else title?.focus({preventScroll:true});modal.scrollTop=0;}
