async function exportPack(){const issues=warnings();if(issues.length){navigate('review');toast('Пак не готов: '+issues[0]);return;}try{const out=structuredClone(pack);out.format='shelter42-user-pack-prototype';for(const id of Object.keys(out.cards))if(!canImage(id))out.cards[id]=out.cards[id].map(({image,...card})=>card);for(const c of out.cards.disaster){delete c.image;delete c.duration;delete c.population;for(const spec of DISASTER_IMAGES){const rec=c.images[spec.id],blob=await readDisasterAsset(rec.assetId);if(!blob)throw Error('Не найден файл «'+spec.name+'». Загрузите его повторно.');rec.dataUrl=await fileDataUrl(blob);delete rec.assetId;}}for(const c of out.cards.disaster){if(c.audio_guide?.assetId){const blob=await readDisasterAsset(c.audio_guide.assetId);if(!blob)throw Error('Не найден файл озвучки. Загрузите его повторно.');c.audio_guide.dataUrl=await fileDataUrl(blob);delete c.audio_guide.assetId;}}out.cards.special=selectedSpecial(out).map(c=>({...c,sourceId:c.id}));const blob=new Blob([JSON.stringify(out,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=(out.name||'Мой пак').replace(/[<>:"/\\|?*]/g,'-')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Пак экспортирован в JSON');}catch(err){toast(err.message||'Не удалось экспортировать пак.');}}
