document.addEventListener('input',e=>{const n=e.target;if(n.id==='pack-name'){n.setCustomValidity('');return;}if(n.id==='catalog-search'){catalogQuery=n.value;$('#catalog-results').innerHTML=catalogResults();$('#catalog-theme-filters').innerHTML=catalogThemeFilters();return;}if(n.id==='card-search'){query=n.value;$('#card-list').innerHTML=cardList();$('#result-count').textContent=filteredCards().length+' найдено';return;}if(!n.dataset.field)return;const key=n.dataset.field;const target=n.dataset.card?pack.cards[section].find(c=>c.id===n.dataset.card):pack;if(!target)return;if(section==='special'&&n.dataset.card&&!['name','description'].includes(key))return;if(key==='typeName')target.category_name=n.value;target[key]=n.type==='number'?(n.value===''?null:Number(n.value)):n.value;if(n.dataset.card){const t=$('[data-card-'+(key==='name'?'name':'desc')+'="'+target.id+'"]');if(t&&['name','description'].includes(key))t.textContent=n.value||(key==='name'?'Новая карточка':requiresCardDescription(section)?'Добавьте описание карточки':'Описание необязательно');}persist();});
document.addEventListener('change',async e=>{
 const n=e.target;if(!n.dataset.imageInput)return;const f=n.files?.[0];if(!f)return;
 const targetPack=pack,targetSection=section,targetId=opened,cover=n.dataset.imageInput==='cover';
 const targetCard=cover?null:targetPack.cards[targetSection]?.find(c=>c.id===targetId);
 if(!cover&&(!targetCard||!canImage(targetSection)))return;
 try{
  if(!['image/jpeg','image/png','image/webp'].includes(f.type))throw Error('Выберите JPG, PNG или WebP');
  if(!f.size||f.size>(cover?1:3)*1024*1024)throw Error('Изображение должно быть не больше '+(cover?1:3)+' МБ и не должно быть пустым');
  const size=await imageDimensions(f);if(!size.width||!size.height)throw Error('Изображение повреждено.');
  const image=await fileDataUrl(f);
  if(!library.includes(targetPack)||(!cover&&!targetPack.cards[targetSection].includes(targetCard)))return;
  const target=cover?targetPack:targetCard,key=cover?'cover':'image',previous=target[key],updatedAt=targetPack.updatedAt;
  target[key]=image;targetPack.updatedAt=new Date().toISOString();
  if(!saveLibrary()){target[key]=previous;targetPack.updatedAt=updatedAt;throw Error(persistError);}
  if(pack===targetPack){refreshMeta();refreshEditorFeedback();if(section===targetSection){render();if(supportsTable(section)&&opened)openCard(opened);}}
  toast('Изображение добавлено');
 }catch(error){toast(error.message||'Не удалось прочитать изображение');}finally{n.value='';}
});

function gridCards(){const cards=filteredCards();return '<div class="cards-grid">'+cards.map(c=>'<article class="grid-card" data-name-card="'+c.id+'"><span class="grid-card-type" data-category="'+section+'">'+esc(c.typeName?.trim()||cats.find(x=>x.id===section).name)+'</span>'+(canImage(section)&&c.image?'<img class="grid-card-image" src="'+esc(c.image)+'" alt="">':'')+'<strong>'+esc(c.name||'Новая карточка')+'</strong>'+duplicateMark(c)+missingDescriptionMark(c)+missingCardImageMark(c)+'<p>'+esc(c.description?.trim()?c.description:requiresCardDescription(section)?'':'Описание необязательно')+'</p><div class="grid-card-bottom">'+btn(icon('edit')+'Редактировать','card-edit-mini','data-edit-card="'+c.id+'" aria-label="Редактировать карточку '+esc(c.name||'Без названия')+'"')+btn(icon('trash'),'card-delete-mini','data-delete="'+c.id+'" title="Удалить карточку" aria-label="Удалить карточку '+esc(c.name||'Без названия')+'"')+'</div></article>').join('')+'<button type="button" class="grid-card add-grid-card" data-add="true"><span class="add-grid-icon">'+icon('plus')+'</span><strong>Добавить новую карточку</strong><span>Название и описание</span></button></div>'+((query||readinessFilter!=='all')&&!cards.length?'<p class="hint no-results">Карточек по выбранным условиям нет. Измените фильтр или поиск.</p>':'');}
