function typePicker(c){if(section==='special')return '';const name=cats.find(t=>t.id===section)?.name||'';return '<div class="field"><label for="card-type">Тип карточки</label><input id="card-type" value="'+esc(name)+'" disabled aria-disabled="true"><span class="hint">Тип карточки закреплён. Если хотите изменить его название в игре, укажите своё ниже.</span></div>'+field('Новое название типа карт',c.category_name||c.typeName||'','typeName',{card:c.id,max:40,hint:'Оставьте пустым, чтобы использовать название «'+esc(name)+'».'});}
