function statisticsChart(data,date){
 const width=840,height=280,left=48,right=22,bottom=36,top=16,plot=height-bottom-top,base=height-bottom,max=Math.max(1,...data.rows.map(r=>r[statisticsSeries])),ceiling=Math.max(4,Math.ceil(max/4)*4),step=(width-left-right)/Math.max(1,data.rows.length-1),x=i=>left+i*step,y=n=>base-n/ceiling*plot;
 let svg='';for(let i=0;i<=4;i++){const gy=y(ceiling*i/4);svg+='<line class="chart-grid" x1="'+left+'" x2="'+(width-right)+'" y1="'+gy+'" y2="'+gy+'"/><text class="chart-label" x="'+(left-10)+'" y="'+(gy+4)+'" text-anchor="end">'+ceiling*i/4+'</text>';}
 const points=key=>data.rows.map((r,i)=>x(i)+','+y(r[key])).join(' ');
 if(statisticsSeries==='total')svg+='<polygon class="chart-total-area" points="'+left+','+base+' '+points('total')+' '+x(data.rows.length-1)+','+base+'"/>';
 for(const key of (statisticsSeries==='total'?['total','unfinished','completed']:[statisticsSeries]))svg+='<polyline class="chart-series chart-line-'+key+'" points="'+points(key)+'"/>';
 data.rows.forEach((r,i)=>{svg+='<rect class="chart-hover" data-chart-day="'+r.date+'" data-completed="'+r.completed+'" data-unfinished="'+r.unfinished+'" data-total="'+r.total+'" data-chart-x="'+x(i)+'" tabindex="0" aria-label="'+date(r.date)+': всего '+r.total+', завершено '+r.completed+', не завершено '+r.unfinished+'" x="'+(x(i)-step/2)+'" y="'+top+'" width="'+step+'" height="'+plot+'"></rect>';const labelStep=data.rows.length<=7?1:data.rows.length<=30?3:7,major=i%labelStep===0||i===data.rows.length-1,showLabel=i%labelStep===0;svg+='<line class="chart-date-tick" x1="'+x(i)+'" x2="'+x(i)+'" y1="'+base+'" y2="'+(base+(major?7:3))+'"/>';if(major)svg+='<line class="chart-date-grid" x1="'+x(i)+'" x2="'+x(i)+'" y1="'+top+'" y2="'+base+'"/>';if(showLabel||i===data.rows.length-1)svg+='<text class="chart-label" x="'+x(i)+'" y="'+(height-10)+'" text-anchor="'+(i!==data.rows.length-1&&data.rows.length-1-i<labelStep?'end':'middle')+'">'+date(r.date)+'</text>';});
 return '<div class="statistics-chart-wrap"><div class="statistics-tooltip" role="status" hidden></div><svg class="statistics-chart" viewBox="0 0 '+width+' '+height+'" role="img" aria-label="Игры по дням: всего '+data.total+', завершено '+data.completed+', не завершено '+data.unfinished+'. Точные значения в таблице ниже.">'+svg+'<line class="chart-cursor" y1="16" y2="244" hidden /></svg></div>';
}
function sampleGameStatistics(){return {daily:gameStatistics({daily:[]},90).rows.map((r,i)=>{const wave=Math.round(36+12*Math.sin(i*.42)+7*Math.cos(i*.19)+i*.16);return {date:r.date,completed:Math.max(8,wave),unfinished:Math.max(2,Math.round(8+4*Math.sin(i*.67)+i%5))};})};}
function statisticsSummary(data,date){const peak=data.rows.reduce((a,b)=>b.total>a.total?b:a,data.rows[0]);return '<p class="statistics-summary">За последние '+data.rows.length+' дней в среднем <strong>'+Math.round(data.total/data.rows.length)+'</strong> игр в день. Максимум — <strong>'+peak.total+'</strong> ('+date(peak.date)+'). Дошли до финала — <strong>'+(data.total?Math.round(data.completed/data.total*100):0)+'%</strong> игр.</p>';}

function showStatisticsDay(target){const day=target.closest?.('[data-chart-day]');if(!day)return;const wrap=day.closest('.statistics-chart-wrap'),tip=wrap.querySelector('.statistics-tooltip'),cursor=wrap.querySelector('.chart-cursor'),d=day.dataset;const date=new Date(d.chartDay+'T00:00:00Z').toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'});tip.innerHTML='<strong>'+date+'</strong>'+[['total','Всего'],['completed','Завершено'],['unfinished','Не завершено']].filter(([key])=>statisticsSeries==='total'||statisticsSeries===key).map(([key,label])=>'<span>'+label+'<b>'+Number(d[key]).toLocaleString('ru-RU')+'</b></span>').join('');tip.hidden=false;const percent=Number(d.chartX)/840*100;tip.style.left=Math.min(98,Math.max(2,percent))+'%';tip.style.transform=percent>65?'translateX(-100%)':percent<30?'none':'translateX(-50%)';cursor.setAttribute('x1',d.chartX);cursor.setAttribute('x2',d.chartX);cursor.removeAttribute('hidden');}
