async function prepareCardAudio(file){
  validateAudioFile(file);
  const src=URL.createObjectURL(file);
  try{
   await new Promise((resolve,reject)=>{
    const audio=new Audio(),timer=setTimeout(()=>{audio.src='';reject(Error('Не удалось прочитать аудиофайл.'));},10000);
    const done=error=>{clearTimeout(timer);audio.onloadedmetadata=audio.onerror=null;audio.removeAttribute('src');audio.load();error?reject(error):resolve();};
    audio.onloadedmetadata=()=>done(Number.isFinite(audio.duration)&&audio.duration>0?null:Error('Аудиофайл пуст или повреждён.'));
    audio.onerror=()=>done(Error('Аудиофайл повреждён или не поддерживается.'));audio.preload='metadata';audio.src=src;
   });
   const assetId=uid();await saveDisasterAsset(assetId,file);disasterAssetUrls.set(assetId,src);
   return {assetId,name:file.name,bytes:file.size,mime:file.type};
  }catch(error){URL.revokeObjectURL(src);throw error;}

}

